import * as THREE from 'three';
export class Player{constructor(camera,world,input){this.camera=camera;this.world=world;this.input=input;this.pos=new THREE.Vector3(0,1.7,15);this.vel=new THREE.Vector3;this.health=100;this.crouch=false}reset(){this.pos.set(0,1.7,15);this.vel.set(0,0,0);this.health=100}step(dt){const i=this.input;this.crouch=i.down('ControlLeft')||i.down('ControlRight');const speed=this.crouch?3.2:6.5;const f=new THREE.Vector3(Math.sin(i.yaw),0,Math.cos(i.yaw)),r=new THREE.Vector3(f.z,0,-f.x),wish=new THREE.Vector3;if(i.down('KeyW'))wish.add(f);if(i.down('KeyS'))wish.sub(f);if(i.down('KeyD'))wish.add(r);if(i.down('KeyA'))wish.sub(r);if(wish.lengthSq())wish.normalize().multiplyScalar(speed);this.vel.x+=(wish.x-this.vel.x)*Math.min(1,dt*12);this.vel.z+=(wish.z-this.vel.z)*Math.min(1,dt*12);const nx=this.pos.x+this.vel.x*dt,nz=this.pos.z+this.vel.z*dt;if(!this.world.collides(nx,this.pos.z))this.pos.x=nx;else this.vel.x=0;if(!this.world.collides(this.pos.x,nz))this.pos.z=nz;else this.vel.z=0;this.camera.position.copy(this.pos);this.camera.position.y=this.crouch?1.1:1.7;this.camera.rotation.set(i.pitch,i.yaw,0)}}
