import * as THREE from 'three';
export class Weapon{constructor(camera,scene,world,input,player){this.camera=camera;this.scene=scene;this.world=world;this.input=input;this.player=player;this.mag=30;this.reserve=90;this.name='VANGUARD';this.grenade=false;this.cool=0;this.ray=new THREE.Raycaster();this.flash=0}reset(){this.mag=30;this.reserve=90;this.name='VANGUARD';this.grenade=false}select(n){this.name=n;this.mag=n==='RIPTIDE'?12:30;this.reserve=n==='RIPTIDE'?48:90}step(dt){this.cool-=dt;if(this.input.pressed('KeyR')&&this.mag<30&&this.reserve){const n=Math.min(30-this.mag,this.reserve);this.mag+=n;this.reserve-=n}if(this.input.buttons&&this.cool<=0&&this.mag>0){this.mag--;this.cool=this.name==='RIPTIDE'?.32:.1;this.flash=.05;this.scene.dispatchEvent({type:'shot',weapon:this})}if(this.input.pressed('KeyG')&&this.grenade){this.grenade=false;this.scene.dispatchEvent({type:'grenade'})}}}
