import * as THREE from 'three';
export class Bots{constructor(scene,world,player,weapon){this.scene=scene;this.world=world;this.player=player;this.weapon=weapon;this.units=[];this.alive=0;scene.addEventListener('shot',e=>this.hit(e.weapon))}reset(round){for(const u of this.units)this.scene.remove(u.mesh);this.units=[];const spots=[[-15,-14],[15,-14],[-15,12],[15,12],[0,-4]];for(const [x,z] of spots){const m=new THREE.Mesh(new THREE.CapsuleGeometry(.55,1.1,4,8),new THREE.MeshStandardMaterial({color:0xd85b52,roughness:.7}));m.position.set(x,1.15,z);m.castShadow=true;this.scene.add(m);this.units.push({mesh:m,hp:100,route:z});}this.alive=this.units.length}hit(weapon){if(!this.alive)return;const f=new THREE.Vector3(0,0,-1).applyQuaternion(this.player.camera.quaternion);let best=null,bd=999;for(const u of this.units){if(u.hp<=0)continue;const d=u.mesh.position.distanceTo(this.player.pos);const dot=f.dot(u.mesh.position.clone().sub(this.player.pos).normalize());if(dot>.985&&d<bd&&!this.world.collides((u.mesh.position.x+this.player.pos.x)/2,(u.mesh.position.z+this.player.pos.z)/2)){best=u;bd=d}}if(best){best.hp-=weapon.name==='RIPTIDE'?48:34;this.scene.dispatchEvent({type:'hit'});if(best.hp<=0){best.mesh.visible=false;this.alive--}}}step(dt){for(const u of this.units){if(u.hp<=0)continue;const d=u.mesh.position.distanceTo(this.player.pos);if(d<18){this.player.health-=dt*(d<8?9:3)}}}objective(){this.scene.dispatchEvent({type:'objective'})}}
